const D = { energy:.5, hue:200, ripples:.6, shimmer:.6, reflect:.5, tint:.6, x:.5, y:.4, scale:1, speed:1, density:.5, style:'pool', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const s = Math.sin((i*12.9898 + P.seed*78.233)) * 43758.5453; return s - Math.floor(s); };
const W=width,H=height,t=K.t,en=P.energy,sty=P.style,dc=drawingContext,TAU=Math.PI*2;
const hor=H*(0.3+(P.y-0.5)*0.3);

let watT=[P.hue,70,45], watB=[P.hue+10,80,20], rip=[P.hue-15,40,95], shimc=[P.hue-20,30,100];
if(sty==='pond'){ watT=[150,55,35]; watB=[140,65,16]; rip=[110,40,80]; shimc=[80,30,90]; }
else if(sty==='ocean'){ watT=[205,75,42]; watB=[215,85,16]; rip=[195,45,95]; shimc=[190,30,100]; }
else if(sty==='neon'){ watT=[P.hue,60,20]; watB=[P.hue,70,10]; rip=[(P.hue+150)%360,90,100]; shimc=[(P.hue+150)%360,90,100]; }
else if(sty==='sunset'){ watT=[15,60,45]; watB=[280,50,20]; rip=[35,60,100]; shimc=[40,50,100]; }
function Cc(a,al){ return color(a[0],a[1],a[2],(al==null?100:al)*P.alpha/100); }

// water gradient (below horizon)
let g=dc.createLinearGradient(0,hor,0,H); g.addColorStop(0,Cc(watT,100).toString()); g.addColorStop(1,Cc(watB,100).toString()); dc.fillStyle=g; noStroke(); rect(0,hor,W,H-hor+1);

// horizon reflection band + tint from "sky"
dc.save(); blendMode(SCREEN); fill(Cc(shimc, 10*P.reflect)); rect(0,hor,W,H*0.14); dc.restore();

// horizontal shimmer lines (perspective — denser far, wobbling)
if(P.shimmer>0.05){ dc.save(); blendMode(SCREEN);
  for(let i=0;i<40;i++){ const z=i/40; const yy=hor + (H-hor)*(z*z); const amp=(8+z*24)*P.shimmer; stroke(Cc(shimc, (6+z*14)*P.shimmer));
    strokeWeight(0.8+z*1.6); noFill(); beginShape(); for(let x=0;x<=W;x+=W/24){ vertex(x, yy+Math.sin(x*0.02+t*(1+z)+i)*amp*0.3);} endShape(); }
  dc.restore(); blendMode(BLEND); }

// EXPANDING RIPPLE RINGS (robust motion)
if(P.ripples>0.05){ dc.save(); blendMode(SCREEN); noFill();
  const nr=Math.floor(2+P.ripples*5);
  for(let i=0;i<nr;i++){ const rx=(0.15+fr(i)*0.7)*W; const zz=0.2+fr(i+5)*0.7; const ry=hor+(H-hor)*(zz*zz);
    const period=3.0+fr(i+2)*2.5; const ph=((t*(0.5+en*0.5)*P.speed)/period + fr(i+9))%1;
    for(let ring=0;ring<3;ring++){ const rr=(ph*1.0 + ring*0.33); const rad=rr*(50+zz*90); const a=(1-rr)*(40*P.ripples);
      stroke(Cc(rip, a)); strokeWeight(1.4);
      dc.save(); dc.translate(rx,ry); dc.scale(1,0.35); dc.beginPath(); dc.arc(0,0,rad,0,TAU); dc.stroke(); dc.restore(); }
  }
  dc.restore(); blendMode(BLEND); }

// specular sun/moon glint reflection (wavering column)
if(P.reflect>0.05){ dc.save(); blendMode(SCREEN); const gx=W*(0.5+(P.x-0.5)*0.8);
  for(let yy=hor; yy<H; yy+=6){ const z=(yy-hor)/(H-hor); const wob=Math.sin(yy*0.1+t*3)*(6+z*30); fill(Cc(shimc, (14*(1-z*0.6))*P.reflect)); ellipse(gx+wob, yy, (10+z*40)*P.reflect, 4); }
  dc.restore(); blendMode(BLEND); }
blendMode(BLEND); dc.shadowBlur=0;
